<section class="commerce-auth shell"><div class="commerce-auth-card"><p class="kicker">Private client account</p><h1>Create your Atelier.</h1><p>Save addresses and follow every order from confirmation to delivery.</p><form method="post" action="<?=e(url('/account/register'))?>" class="commerce-form"><?=csrf_field()?><label>Full name<input name="name" autocomplete="name" required></label><label>Email<input type="email" name="email" autocomplete="email" required></label><label>Phone<input name="phone" inputmode="tel" autocomplete="tel"></label><label>Password<input type="password" name="password" autocomplete="new-password" minlength="10" required><small>Use at least 10 characters.</small></label><button class="btn dark wide" type="submit">Create account</button></form><div class="auth-links"><span>Already registered?</span><a href="<?=e(url('/account/login'))?>">Sign in →</a></div></div></section>
